CREATE TABLE users (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(100) NOT NULL,role VARCHAR(16) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,career VARCHAR(100) NOT NULL DEFAULT '',university VARCHAR(100) NOT NULL DEFAULT '',birth_date VARCHAR(10),guardian VARCHAR(200),consent_at VARCHAR(30));
CREATE TABLE auth_tokens (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,user_id VARCHAR(36) NOT NULL,token_hash VARCHAR(64) NOT NULL UNIQUE,expires_at VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE settings (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,name VARCHAR(150) NOT NULL,warning_pct INT NOT NULL,low_grade DECIMAL(5,2) NOT NULL,high_grade DECIMAL(5,2) NOT NULL,weights TEXT NOT NULL);
CREATE TABLE cycles (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,name VARCHAR(100) NOT NULL,start_date VARCHAR(10) NOT NULL,end_date VARCHAR(10) NOT NULL,closed BOOLEAN NOT NULL DEFAULT FALSE,weights TEXT NOT NULL);
CREATE TABLE sections (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,cycle_id VARCHAR(36) NOT NULL,name VARCHAR(100) NOT NULL,capacity INT NOT NULL,FOREIGN KEY(cycle_id) REFERENCES cycles(id),UNIQUE(cycle_id,name));
CREATE TABLE courses (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,name VARCHAR(100) NOT NULL UNIQUE,description TEXT);
CREATE TABLE offerings (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,course_id VARCHAR(36) NOT NULL,section_id VARCHAR(36) NOT NULL,teacher_id VARCHAR(36) NOT NULL,syllabus TEXT,progress INT NOT NULL DEFAULT 0,FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(section_id) REFERENCES sections(id),FOREIGN KEY(teacher_id) REFERENCES users(id),UNIQUE(course_id,section_id),CHECK(progress BETWEEN 0 AND 100));
CREATE TABLE enrollments (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,student_id VARCHAR(36) NOT NULL,offering_id VARCHAR(36) NOT NULL,joined_on VARCHAR(10) NOT NULL,withdrawn_on VARCHAR(10),FOREIGN KEY(student_id) REFERENCES users(id),FOREIGN KEY(offering_id) REFERENCES offerings(id),UNIQUE(student_id,offering_id));
CREATE TABLE sessions (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,offering_id VARCHAR(36) NOT NULL,date VARCHAR(10) NOT NULL,starts VARCHAR(5) NOT NULL,ends VARCHAR(5) NOT NULL,room VARCHAR(80) NOT NULL,topic VARCHAR(200) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'PROGRAMADA',FOREIGN KEY(offering_id) REFERENCES offerings(id),UNIQUE(offering_id,date,starts));
CREATE TABLE attendance (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,session_id VARCHAR(36) NOT NULL,student_id VARCHAR(36) NOT NULL,state VARCHAR(16) NOT NULL,note VARCHAR(400),recorded_by VARCHAR(36) NOT NULL,FOREIGN KEY(session_id) REFERENCES sessions(id),FOREIGN KEY(student_id) REFERENCES users(id),UNIQUE(session_id,student_id),CHECK(state IN ('PRESENTE','TARDE','FALTA','JUSTIFICADO')));
CREATE TABLE materials (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,offering_id VARCHAR(36) NOT NULL,author_id VARCHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,topic VARCHAR(150) NOT NULL,difficulty VARCHAR(20) NOT NULL,tags VARCHAR(300),archived BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(offering_id) REFERENCES offerings(id),FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE material_versions (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,material_id VARCHAR(36) NOT NULL,version INT NOT NULL,body LONGTEXT NOT NULL,url VARCHAR(1000),file_key VARCHAR(100),file_name VARCHAR(255),mime VARCHAR(120),reason VARCHAR(400),FOREIGN KEY(material_id) REFERENCES materials(id),UNIQUE(material_id,version));
CREATE TABLE questions (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,course_id VARCHAR(36) NOT NULL,author_id VARCHAR(36) NOT NULL,topic VARCHAR(150) NOT NULL,difficulty VARCHAR(20) NOT NULL,practice BOOLEAN NOT NULL DEFAULT TRUE,archived BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE question_versions (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,question_id VARCHAR(36) NOT NULL,version INT NOT NULL,kind VARCHAR(20) NOT NULL,prompt TEXT NOT NULL,options TEXT NOT NULL,answer TEXT NOT NULL,explanation TEXT NOT NULL,FOREIGN KEY(question_id) REFERENCES questions(id),UNIQUE(question_id,version));
CREATE TABLE exams (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,offering_id VARCHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,category VARCHAR(20) NOT NULL,opens_at VARCHAR(30) NOT NULL,closes_at VARCHAR(30) NOT NULL,release_at VARCHAR(30) NOT NULL,duration INT NOT NULL,max_attempts INT NOT NULL,university VARCHAR(100) NOT NULL DEFAULT '',career VARCHAR(100) NOT NULL DEFAULT '',archived BOOLEAN NOT NULL DEFAULT FALSE,FOREIGN KEY(offering_id) REFERENCES offerings(id),CHECK(duration BETWEEN 1 AND 240),CHECK(max_attempts BETWEEN 1 AND 10));
CREATE TABLE exam_questions (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,exam_id VARCHAR(36) NOT NULL,question_version_id VARCHAR(36) NOT NULL,position INT NOT NULL,points DECIMAL(6,2) NOT NULL,FOREIGN KEY(exam_id) REFERENCES exams(id),FOREIGN KEY(question_version_id) REFERENCES question_versions(id),UNIQUE(exam_id,position));
CREATE TABLE attempts (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,exam_id VARCHAR(36) NOT NULL,student_id VARCHAR(36) NOT NULL,number INT NOT NULL,deadline VARCHAR(30) NOT NULL,submitted_at VARCHAR(30),status VARCHAR(20) NOT NULL,grade DECIMAL(5,2),feedback TEXT,FOREIGN KEY(exam_id) REFERENCES exams(id),FOREIGN KEY(student_id) REFERENCES users(id),UNIQUE(exam_id,student_id,number),CHECK(grade IS NULL OR grade BETWEEN 0 AND 20));
CREATE TABLE responses (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,attempt_id VARCHAR(36) NOT NULL,exam_question_id VARCHAR(36) NOT NULL,answer TEXT,points DECIMAL(6,2),feedback TEXT,FOREIGN KEY(attempt_id) REFERENCES attempts(id),FOREIGN KEY(exam_question_id) REFERENCES exam_questions(id),UNIQUE(attempt_id,exam_question_id));
CREATE TABLE grades (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,offering_id VARCHAR(36) NOT NULL,student_id VARCHAR(36) NOT NULL,title VARCHAR(150) NOT NULL,category VARCHAR(20) NOT NULL,grade DECIMAL(5,2) NOT NULL,recorded_by VARCHAR(36) NOT NULL,FOREIGN KEY(offering_id) REFERENCES offerings(id),FOREIGN KEY(student_id) REFERENCES users(id),CHECK(grade BETWEEN 0 AND 20));
CREATE TABLE resolutions (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,question_id VARCHAR(36) NOT NULL,author_id VARCHAR(36) NOT NULL,body LONGTEXT NOT NULL,version INT NOT NULL DEFAULT 1,status VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE',reviewer_id VARCHAR(36),feedback TEXT,FOREIGN KEY(question_id) REFERENCES questions(id),FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE resolution_history (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,resolution_id VARCHAR(36) NOT NULL,version INT NOT NULL,body LONGTEXT NOT NULL,FOREIGN KEY(resolution_id) REFERENCES resolutions(id));
CREATE TABLE bulletins (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,title VARCHAR(200) NOT NULL,university VARCHAR(100) NOT NULL,career VARCHAR(100) NOT NULL,admission_year INT NOT NULL,process VARCHAR(100) NOT NULL,file_key VARCHAR(100),file_name VARCHAR(255),url VARCHAR(1000),description TEXT,version INT NOT NULL DEFAULT 1,bulletin_group VARCHAR(36) NOT NULL,archived BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE challenges (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,offering_id VARCHAR(36) NOT NULL,creator_id VARCHAR(36) NOT NULL,opponent_id VARCHAR(36) NOT NULL,questions LONGTEXT NOT NULL,expires_at VARCHAR(30) NOT NULL,FOREIGN KEY(offering_id) REFERENCES offerings(id),FOREIGN KEY(creator_id) REFERENCES users(id),FOREIGN KEY(opponent_id) REFERENCES users(id));
CREATE TABLE challenge_results (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,challenge_id VARCHAR(36) NOT NULL,user_id VARCHAR(36) NOT NULL,answers LONGTEXT NOT NULL,score INT NOT NULL,FOREIGN KEY(challenge_id) REFERENCES challenges(id),FOREIGN KEY(user_id) REFERENCES users(id),UNIQUE(challenge_id,user_id));
CREATE TABLE vocational (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,student_id VARCHAR(36) NOT NULL,instrument VARCHAR(60) NOT NULL,answers LONGTEXT NOT NULL,preferences TEXT NOT NULL,result LONGTEXT,status VARCHAR(20) NOT NULL,updated_at VARCHAR(30) NOT NULL,FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE universities (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,name VARCHAR(200) NOT NULL,acronym VARCHAR(30) NOT NULL,city VARCHAR(100) NOT NULL,public_university BOOLEAN NOT NULL DEFAULT TRUE,source_url VARCHAR(1000) NOT NULL,verified_on VARCHAR(10),careers TEXT NOT NULL,note VARCHAR(500));
CREATE TABLE notifications (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,user_id VARCHAR(36) NOT NULL,title VARCHAR(200) NOT NULL,body TEXT NOT NULL,severity VARCHAR(20) NOT NULL,dedup_key VARCHAR(190) UNIQUE,read_at VARCHAR(30),emailed BOOLEAN NOT NULL DEFAULT FALSE,retries INT NOT NULL DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE chat_messages (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,user_id VARCHAR(36) NOT NULL,question TEXT NOT NULL,answer LONGTEXT NOT NULL,sources TEXT NOT NULL,provider VARCHAR(30) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,user_id VARCHAR(36) NOT NULL,action VARCHAR(100) NOT NULL,entity_id VARCHAR(100) NOT NULL,details LONGTEXT NOT NULL);
CREATE TABLE report_cards (id VARCHAR(36) PRIMARY KEY,created_at VARCHAR(30) NOT NULL,cycle_id VARCHAR(36) NOT NULL,student_id VARCHAR(36) NOT NULL,version INT NOT NULL,snapshot LONGTEXT NOT NULL,issued_by VARCHAR(36) NOT NULL,FOREIGN KEY(cycle_id) REFERENCES cycles(id),FOREIGN KEY(student_id) REFERENCES users(id),UNIQUE(cycle_id,student_id,version));
CREATE INDEX idx_enrollments_offering_id ON enrollments(offering_id);
CREATE INDEX idx_attendance_student_id ON attendance(student_id);
CREATE INDEX idx_offerings_teacher_id ON offerings(teacher_id);
CREATE INDEX idx_attempts_student_id ON attempts(student_id);
CREATE INDEX idx_materials_offering_id ON materials(offering_id);
CREATE INDEX idx_notifications_user_id ON notifications(user_id);
CREATE INDEX idx_vocational_student_id ON vocational(student_id);
